/* See sub_003DEA53: relink a circular guest LIST_ENTRY whose walk did not come
 * back to its head. Keeps the nodes reachable from the head without a repeat
 * or an invalid pointer, fixes their back links and closes the list. */
static int ma2_xact_list_node_ok(uint32_t a)
{
    return !(a & 3u) && ((a >= 0x00010000u && a < 0x03FFFFF8u) || (a >= 0x80000000u && a < 0x83FFFFF8u));
}
void ma2_xact_list_repair(uint32_t head, unsigned offset)   /* also used by recomp_0098.c */
{
    enum { MAX_NODES = 4096, SET = 16384 };
    static uint32_t seen[SET];
    static unsigned reports;
    uint32_t prev = head, cur = MEM32(head), bad = 0;
    unsigned kept = 0;
    const char *why = "too long";
    memset(seen, 0, sizeof seen);
    for (;;) {
        if (cur == head) { why = "long but closed"; break; }
        if (!ma2_xact_list_node_ok(cur)) { why = "invalid link"; bad = cur; break; }
        unsigned h = (unsigned)((cur * 2654435761u) >> 18) & (SET - 1);
        while (seen[h] && seen[h] != cur) h = (h + 1) & (SET - 1);
        if (seen[h] == cur) { why = "cycle without head"; bad = cur; break; }
        if (kept >= MAX_NODES) { bad = cur; break; }
        seen[h] = cur;
        MEM32(cur + 4) = prev;          /* Blink */
        prev = cur; kept++;
        cur = MEM32(cur);
    }
    MEM32(prev) = head;
    MEM32(head + 4) = prev;
    if (reports++ < 16) {
        fprintf(stderr, "[XACT-LIST] engine list +0x%02X head=%08X relinked: %s at %08X, %u nodes kept\n",
                offset, head, why, bad, kept);
        fflush(stderr);
    }
}

/* The step counter above caught a broken list only after 4096 steps: a node whose
 * Flink was 0 (freed or zeroed while still linked) sent the walk through garbage
 * nodes first (esi = 0, then whatever guest [0] holds), calling the per-node
 * handler on each -- the wild [ICALL]s before every [XACT-LIST] line and the
 * notification-callback crash after it (Not It NRC, batch 2 + 3, 2026-10-27).
 * Now every step checks the next link before it is used and the list is cut
 * at the bad link at once (no node handler runs on it). */
uint32_t g_ma2_xact_engine;                 /* sub_003DEA53's engine object (edi) */
static int ma2_xact_uaf_on(void)
{
    static int on = -1;
    if (on < 0) { const char *e = getenv("RECOMP_XACT_UAF"); on = e && *e && *e != '0'; }
    return on;
}
/* RECOMP_XACT_UAF=1: a ring of recent guest heap frees with their guest return
 * addresses, so the walk that meets a dead node can say who freed it. */
enum { MA2_XFREE_RING = 512, MA2_XFREE_RA = 10 };
static struct { uint32_t addr, size, ra[MA2_XFREE_RA]; unsigned seq; } g_xfree[MA2_XFREE_RING];
static volatile long g_xfree_n;
static unsigned ma2_guest_ra(uint32_t *ra, unsigned max)
{
    unsigned n = 0;
    if (!g_xbox_mem_offset || !g_esp) return 0;
    for (unsigned i = 0; i < 256 && n < max; i++) {
        uint32_t a = g_esp + i * 4u;
        if (a < 0x00010000u || a >= 0x03FFFFF0u) break;
        uint32_t v = MEM32(a);
        if (v > g_xbox_code_lo && v < g_xbox_code_hi) ra[n++] = v;
    }
    return n;
}
static void ma2_xact_print_ra(const uint32_t *ra, unsigned n)
{
    for (unsigned i = 0; i < n; i++) fprintf(stderr, "%s%08X", i ? " " : "", ra[i]);
}
/* Is node (a LIST_ENTRY address) linked on one of the engine's three lists? */
static int ma2_xact_on_list(uint32_t lo, uint32_t hi, uint32_t *node, unsigned *off)
{
    static const unsigned offs[3] = { 0x44, 0x64, 0x5C };
    uint32_t eng = g_ma2_xact_engine;
    if (!eng) return 0;
    for (int l = 0; l < 3; l++) {
        uint32_t head = eng + offs[l], cur = MEM32(head);
        for (unsigned k = 0; k < 4096 && cur != head && ma2_xact_list_node_ok(cur); k++, cur = MEM32(cur))
            if (cur >= lo && cur < hi) { *node = cur; *off = offs[l]; return 1; }
    }
    return 0;
}
void ma2_xact_on_free(uint32_t addr, uint32_t size)    /* xbox_HeapFree, before the block is released */
{
    if (!ma2_xact_uaf_on()) return;
    unsigned seq = (unsigned)InterlockedIncrement(&g_xfree_n);
    unsigned i = seq % MA2_XFREE_RING;
    uint32_t ra[MA2_XFREE_RA]; unsigned n = ma2_guest_ra(ra, MA2_XFREE_RA);
    g_xfree[i].addr = addr; g_xfree[i].size = size; g_xfree[i].seq = seq;
    memset(g_xfree[i].ra, 0, sizeof g_xfree[i].ra); memcpy(g_xfree[i].ra, ra, n * sizeof ra[0]);
    uint32_t node; unsigned off; static unsigned reports;
    if (ma2_xact_on_list(addr, addr + size, &node, &off) && reports++ < 32) {
        fprintf(stderr, "[XACT-UAF] free of block %08X+%X while node %08X is still on engine %08X list +0x%02X; tid=%lu guest ra: ",
                addr, size, node, g_ma2_xact_engine, off, (unsigned long)GetCurrentThreadId());
        ma2_xact_print_ra(ra, n);
        fprintf(stderr, "\n"); fflush(stderr);
    }
}
/* The game's own XMemFree (sub_00012330(ptr, attributes)): XACT's objects come from the game
 * pools by allocator id (attributes byte 2; 0x84 = XACT, its own pool at [0x50BA38]), not from
 * xbox_HeapFree, so the free above never sees them. RECOMP_XACT_UAF=1 records these frees in
 * the same ring (size 0 = pool block, size unknown) and reports a free of an XACT block that
 * still holds a linked engine node. Always: XMemFree(NULL) is a no-op (the game's version read
 * [ptr-0xB] and crashed, Not It NRC batch 3) -- skipped and logged. Returns 1 = skip the free. */
/* Is the object at obj still linked by its own node? Each list's node sits at a fixed place in
 * its object (the walks hand node-0x58 / node-8 / node to their handlers), so only that exact
 * address counts -- a node merely near the freed pointer belongs to a neighbouring block (the
 * first xact2 run reported +0x50..+0x1D8 hits, two blocks for one node: neighbours). */
static int ma2_xact_obj_linked(uint32_t obj, uint32_t *node, unsigned *off)
{
    static const unsigned offs[3] = { 0x44, 0x64, 0x5C }, at[3] = { 0x58, 0x08, 0x00 };
    uint32_t eng = g_ma2_xact_engine;
    if (!eng) return 0;
    for (int l = 0; l < 3; l++) {
        uint32_t head = eng + offs[l], want = obj + at[l], cur = MEM32(head);
        for (unsigned k = 0; k < 4096 && cur != head && ma2_xact_list_node_ok(cur); k++, cur = MEM32(cur))
            if (cur == want) { *node = cur; *off = offs[l]; return 1; }
    }
    return 0;
}
int ma2_xact_on_xmemfree(uint32_t ptr, uint32_t attrs)
{
    unsigned id = (attrs >> 16) & 0xFFu;
    if (!ptr) {
        static unsigned nulls;
        if (nulls++ < 16) {
            uint32_t ra[MA2_XFREE_RA]; unsigned n = ma2_guest_ra(ra, MA2_XFREE_RA);
            fprintf(stderr, "[XACT-FREE] XMemFree(NULL) attrs=%08X (allocator %02X) skipped; tid=%lu guest ra: ", attrs, id, (unsigned long)GetCurrentThreadId());
            ma2_xact_print_ra(ra, n);
            fprintf(stderr, "\n"); fflush(stderr);
        }
        return 1;
    }
    if (!ma2_xact_uaf_on()) return 0;
    unsigned seq = (unsigned)InterlockedIncrement(&g_xfree_n);
    unsigned i = seq % MA2_XFREE_RING;
    uint32_t ra[MA2_XFREE_RA]; unsigned n = ma2_guest_ra(ra, MA2_XFREE_RA);
    g_xfree[i].addr = ptr; g_xfree[i].size = 0; g_xfree[i].seq = seq;
    memset(g_xfree[i].ra, 0, sizeof g_xfree[i].ra); memcpy(g_xfree[i].ra, ra, n * sizeof ra[0]);
    uint32_t node; unsigned off; static unsigned reports;
    if (id == 0x84 && ma2_xact_obj_linked(ptr, &node, &off) && reports++ < 32) {
        fprintf(stderr, "[XACT-UAF] XMemFree of XACT block %08X while node %08X (+%X into it) is still on engine %08X list +0x%02X; tid=%lu guest ra: ",
                ptr, node, node - ptr, g_ma2_xact_engine, off, (unsigned long)GetCurrentThreadId());
        ma2_xact_print_ra(ra, n);
        fprintf(stderr, "\n"); fflush(stderr);
    }
    return 0;
}
/* A walk met a bad next link: cut the list there (no handler runs on it), say where. */
int ma2_xact_walk_bad(uint32_t head, uint32_t next, unsigned offset, unsigned step)
{
    static unsigned reports;
    if (next == head || ma2_xact_list_node_ok(next)) return 0;
    if (reports++ < 16) {
        fprintf(stderr, "[XACT-LIST] engine list +0x%02X head=%08X: bad next link %08X at step %u, cut before any handler ran on it\n",
                offset, head, next, step);
        if (ma2_xact_uaf_on()) {   /* the node holding the bad link, and the last free that covered it */
            uint32_t prev = head, cur = MEM32(head);
            for (unsigned k = 0; k < 4096 && cur != next && cur != head && ma2_xact_list_node_ok(cur); k++) { prev = cur; cur = MEM32(cur); }
            fprintf(stderr, "[XACT-LIST]   bad link sits in node %08X: %08X %08X %08X %08X %08X %08X %08X %08X\n", prev,
                    MEM32(prev - 8), MEM32(prev - 4), MEM32(prev), MEM32(prev + 4), MEM32(prev + 8), MEM32(prev + 12), MEM32(prev + 16), MEM32(prev + 20));
            for (unsigned k = 0; k < MA2_XFREE_RING; k++) {
                unsigned j = ((unsigned)g_xfree_n - k) % MA2_XFREE_RING;
                /* pool block (size 0): only the object whose own node this is (node - 0x58 / 8 / 0) */
                uint32_t want = prev - (offset == 0x44 ? 0x58u : offset == 0x64 ? 8u : 0u);
                if (!g_xfree[j].seq || (g_xfree[j].size ? prev < g_xfree[j].addr || prev >= g_xfree[j].addr + g_xfree[j].size
                                                        : g_xfree[j].addr != want)) continue;
                fprintf(stderr, "[XACT-LIST]   it was freed: free #%u (of %ld) block %08X+%X guest ra ", g_xfree[j].seq, (long)g_xfree_n, g_xfree[j].addr, g_xfree[j].size);
                ma2_xact_print_ra(g_xfree[j].ra, MA2_XFREE_RA);
                fprintf(stderr, "\n");
                break;
            }
        }
        fflush(stderr);
    }
    ma2_xact_list_repair(head, offset);
    return 1;
}
/* RECOMP_XACT_THREAD: which threads run XACT's lock / IRQL helpers (the game thread is the first
 * caller). Another thread here, at raised IRQL, skips the XACT lock: the suspect for the list spins. */
#include <windows.h>
static void ma2_xact_thread_note(int site)
{
    static int on = -1; static DWORD first; static LONG reports;
    if (on < 0) on = getenv("RECOMP_XACT_THREAD") != NULL;
    if (!on) return;
    DWORD t = GetCurrentThreadId();
    if (!first) { first = t; return; }
    if (t != first && InterlockedIncrement(&reports) <= 40)
        fprintf(stderr, "[XACT-THREAD] site=%d tid=%lu (game %lu) irql=%u ret=%08X ret2=%08X\n", site, (unsigned long)t, (unsigned long)first,
                MEM8(XBOX_FS_BASE + 0x24), MEM32(esp), MEM32(esp + 4));
}
